/* Register-level checker for the SPU DMA adapters of batch cdgen44 (family cdx-spu): retail 0x80085E54 (SpuWrite
 * adapter, pe_plat_cdxspu_spu_write) and 0x80085DF4 (SpuRead adapter, pe_plat_cdxspu_spu_read) against
 * cdgen44/regonly.txt (100 cases each; vectors generated by `pe_cdx_vectors.py ... cdgen44 -regonly`).
 * The replay scaffold is pe_cdx_common.h: every SPU / DMA4 / SPU_DELAY register read is replayed in the original's
 * order and every register store is compared in order, width and value; the final guest RAM image and the return
 * value are compared; any other callee or host seam reached by the entry fails the case.
 * The programmed-I/O arm of 80085E54 runs the shared clean-room leaf 8007D454 (platform/pe_plat2_spu_a.c), and the
 * SPU_DELAY priority bits the shared leaves 8007DC5C / 8007DC84, so that object is linked as real code; every
 * symbol the two objects leave undefined is a stand-in below.  Host-only calls (PE_SpuDma_DeliverPending: the host
 * completes a pending DMA before a new issue; its result 1 = nothing pending) are counted, not compared.
 * Build (objects: ninja -C build/dev CMakeFiles/pe_field_runtime.dir/platform/pe_plat2_cdx_spu.c.o CMakeFiles/pe_field_runtime.dir/platform/pe_plat2_spu_a.c.o):
 * BUILD: cc -std=gnu11 -Wall -Wextra -Werror -Ipc_port/include -Ipc_port/platform -Ipc_port/bootstrap pc_port/tools/pe_cdx_cdgen44_regonly_check.c build/dev/CMakeFiles/pe_field_runtime.dir/platform/pe_plat2_cdx_spu.c.o build/dev/CMakeFiles/pe_field_runtime.dir/platform/pe_plat2_spu_a.c.o -o check44reg
 * Run: ./check44reg regonly.txt [noop|flip] */
#include "pe_cdx_common.h"
/* host-only seam: nothing is pending in the vectors */
uint32_t PE_SpuDma_DeliverPending(void) { host_only_calls++; return 1; }
/* seams and callees not reached by these entries: a call fails the case */
TRAP(func_80085084) TRAP(PE_Event_Open) TRAP(PE_Event_Enable) TRAP(pe_plat_reset_callback)
TRAP(pe_plat_spu_set_reverb_mode_type) TRAP(PE_SpuDma_InstallIrq)
TRAP(pe_plat_bios_enter_critical) TRAP(pe_plat_bios_exit_critical) TRAP(pe_plat_bios_close_event)
TRAP(pe_plat_bios_disable_event) TRAP(pe_plat_dma_callback) TRAP(PE_Printf_Guest)
TRAP(func_800850F4) TRAP(PE_SpuDma_WaitForCompletion) TRAP(pe_plat_spu_set_common_attributes) TRAP(pe_plat_spu_voice_volume)
TRAP(pe_plat_ctl_counter_setup) TRAP(pe_plat_ctl_counter_start)
/* cdx-spu2: only the stream bring-up (not an entry of this batch) calls the transfer-address leaf of platform/pe_plat2_spu_b.c */
TRAP(pe_plat_spub_set_transfer_address)
/* cdx-spu2: only the reverb work-area clear (not an entry of this batch) reaches these */
TRAP(pe_plat_spub_heap_contains) TRAP(PE_SpuDma_Service) TRAP(PE_Event_ConsumeSpuDma)
void pe_plat_sio_poll_tick(void) {}
void PE_Decomp_GuestTrapDivZero(const char *fn) { (void)fn; bad_call = 1; trap_name = "PE_Decomp_GuestTrapDivZero"; }
int PE_Port_ShouldStop(void) { return 0; }
void PE_Port_RequestStop(int r) { (void)r; bad_call = 1; trap_name = "PE_Port_RequestStop"; }
uint32_t pe_plat_cdxspu_spu_write(uint32_t source, uint32_t size);
uint32_t pe_plat_cdxspu_spu_read(int guest_destination, unsigned int size);
/* no callee is recorded here (every callee is a TRAP); keep the scaffold helper referenced */
static uint32_t (*const keep_callee)(uint32_t, unsigned, uint32_t, uint32_t, uint32_t, uint32_t, uint32_t) = cdx_callee;
static int call(uint32_t entry, const uint32_t *a, uint32_t *ret)
{
    (void)keep_callee;
    if (mutant == 1) return entry == 0x80085E54u || entry == 0x80085DF4u ? (*ret = 0, 1) : 0;
    switch (entry) {
    case 0x80085E54u: *ret = pe_plat_cdxspu_spu_write(a[0], a[1]); return 1;
    case 0x80085DF4u: *ret = pe_plat_cdxspu_spu_read((int)a[0], a[1]); return 1;
    }
    return -1;
}
